Given a string s and y a dictionary of n words dictionary, check if s can be segmented into a sequence of valid words from the dictionary, separated by spaces.Examples:Input:  s = "ilike", dictionary[] = ["i", "like", "gfg"]Output: trueExplanation: The string can be segmented as "i like".Input:  s = "ilikegfg", dictionary[] = ["i", "like", "man", "india", "gfg"]Output: trueExplanation: The string can be segmented as "i like gfg".Input: "ilikemangoes", dictionary = ["i", "like", "gfg"]Output: falseExplanation: The string cannot be segmented.Try It YourselfTable of Content[Naive Approach] Using Recursion - O(2^n) Time and O(n) Space[Expected Approach - 1] Using Top-Down DP - O(n^2) Time and O(n+m) Spacce[Expected Approach - 2] Using Bottom Up DP - O(n*m*k) time and O(n) space[Naive Approach] Using Recursion - O(2^n) Time and O(n) SpaceThe idea is to consider each prefix and search for it in dictionary. If the prefix is present in dictionary, we recur for rest of the string (or suffix). If the recursive call for suffix returns true, we return true, otherwise we try next prefix. If we have tried all prefixes and none of them resulted in a solution, we return false.
            C++

    // C++ program to implement word break.
#include <bits/stdc++.h>
using namespace std;

// Function to check if the given string can be broken
// down into words from the word list
bool wordBreakRec(int i, string &s, vector<string> &dictionary)
{

    // If end of string is reached,
    // return true.
    if (i == s.length())
        return true;

    int n = s.length();
    string prefix = "";

    // Try every prefix
    for (int j = i; j < n; j++)
    {
        prefix += s[j];

        // if the prefix s[i..j] is a dictionary word
        // and rest of the string can also be broken into
        // valid words, return true
        if (find(dictionary.begin(), dictionary.end(), prefix) != dictionary.end() &&
            wordBreakRec(j + 1, s, dictionary))
        {
            return true;
        }
    }

    return false;
}

bool wordBreak(string &s, vector<string> &dictionary)
{
    return wordBreakRec(0, s, dictionary);
}

int main()
{
    string s = "ilike";

    vector<string> dictionary = {"i", "like", "gfg"};

    cout << (wordBreak(s, dictionary) ? "true" : "false") << endl;

    return 0;
}


